      const text = continuing ? "Continue the unfinished task from the saved results. Briefly explain the next step. The previous console closed when the run stopped; inspect current state and uncertain outcomes before proposing further actions. Do not repeat completed changes." : prompt.value.trim();
      const content = [{ type: "text", text }];
      for (const attachment of continuing ? [] : conversation.attachments)
        content.push(
          attachment.kind === "image" ? { type: "image_url", image_url: { url: attachment.content } } : {
            type: "text",
            text: `Attached file: ${attachment.name}
<untrusted_attachment>
${attachment.content}
</untrusted_attachment>`
          }
        );
      const user = {
        role: "user",
        content: !continuing && conversation.attachments.length ? content : text
      };
      const messages = [
        {
          role: "system",
          content: operatingGuide + hostInstructions(conversation) + `
Accepted workspace: ${JSON.stringify(accepted)}`
        },
        ...conversation.messages,
        user
      ];
      if (new TextEncoder().encode(JSON.stringify(messages)).length > 26e5)
        throw new Error(
          "This conversation is too large for one model request. Export it or start a new conversation with a summary."
        );
      conversation.messages.push(user);
      conversation.title = conversation.title === "New conversation" ? (text || "Image conversation").slice(0, 60) : conversation.title;
      conversation.host = conversation.workspace.name;
      if (!continuing) {
        conversation.draft = "";
        conversation.attachments = [];
        prompt.value = "";
      }
      changed();
      renderThread();
      renderAttachments();
      const initial = messages.length;
      let persisted = initial;
      const sync = () => {
        conversation.messages.push(...messages.slice(persisted));
        persisted = messages.length;
        changed();
      };
      currentAssistant = null;
      currentAssistantText = "";
      try {
        await runAgent({
          network: client.network,
          connection,
          model: model.trim(),
          messages,
          tools: toolsEnabled ? toolkit.tools : [],
          signal: turn.signal,
          limits,
          onRound() {
            sync();
            currentAssistant = null;
            currentAssistantText = "";
          },
          onText(text2) {
            const scroller = $("messages"), follow = scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight < 100;
            if (!text2.trim() && !currentAssistant) return;
            currentAssistant ??= messageCard("assistant", "");
            currentAssistantText = text2;
            richText(currentAssistant, text2);
            $("activity").textContent = "Writing\u2026";
            if (follow) scroller.scrollTop = scroller.scrollHeight;
          },
          onTool(call, state, result) {
            sync();
            toolCard(call, state, result);
            $("activity").textContent = state === "running" ? `Using ${call.function.name.replaceAll("_", " ")}\u2026` : "Thinking about the result\u2026";
          }
        });
        sync();
      } catch (error) {
        sync();
        if (currentAssistantText && messages.at(-1)?.content !== currentAssistantText)
          conversation.partial = currentAssistantText;
        throw error;
      }
    } catch (error) {
      const cause = turn.signal.aborted ? turn.signal.reason : error;
      if (cause instanceof RunPaused) {
        conversation.paused = cause.message;
        notify("");
      } else {
        conversation.error = turn.signal.aborted ? "Stopped. Completed actions remain completed; inspect any uncertain remote outcome before retrying." : error instanceof Error ? error.message : String(error);
        report(conversation.error);
      }
      changed();
    } finally {
      deadline.close();
      await toolkit?.close();
      active = null;
      setBusy(false);
      renderThread();
      await save().catch(report);
      prompt.focus();
    }
  }
  function showSettings(show) {
    $("settings-panel").hidden = !show;
    root.classList.toggle("settings-open", show);
    if (show) {
      $("model-input").value = model;
      $("tools-enabled").checked = toolsEnabled;
      $("run-rounds").value = String(limits.rounds);
      $("run-minutes").value = String(limits.minutes);
      updateConnection();
    }
  }
  function updateConnection() {
    $("model-label").textContent = model || "Connect a model";
    $("endpoint-label").textContent = connection?.endpoint ?? "No endpoint configured";
  }
  async function refreshEnvironment() {
    environment = await client.environment.get();
    applyAppearance(environment);
    renderHostContext();
    $("host-name").textContent = currentHost(environment)?.name ?? environment.host?.name ?? (environment.connection === "local" ? "Local workspace" : "Remote workspace");
    $("host-caption").textContent = environment.connection === "connected" ? environment.host?.system || "Connected through ShellCanvas" : environment.connection === "review-required" ? "Accept the new connection in the window bar" : environment.connection === "disconnected" ? "Disconnected \xB7 conversations stay available" : "Connect a host to use workspace tools";
    const methods = await client.services.list();
    const available = methods.filter(
      (method) => method.available && method.granted
    );
    $("tools-label").textContent = toolsEnabled ? environment.connection === "connected" ? "Workspace tools ready \xB7 changes require review" : "Chat is ready \xB7 no remote tools connected" : "Chat only \xB7 workspace tools off";
    const allowed = (name) => available.some((method) => method.name === name);
    $("attach-remote").disabled = busy || !allowed("system.files.readText") || !allowed("system.dialogs.openFile");
    $("paste-attachment").disabled = busy || !allowed("system.clipboard.readStart") && !allowed("system.clipboard.image.readStart");
    if (active && environment.connection !== "connected" && conversation.host !== "Local workspace")
      active.abort(new Error("Connection changed."));
  }
  async function start() {
    client = await connectToShellCanvas();
    const access = await client.services.list();
    if (!access.some(
      (method) => method.name === "system.storage.put" && method.available && method.granted
    )) {
      client = { ...client, storage: memoryStorage(), settings: memoryStorage() };
      const privacy = root.querySelector(".sidebar-bottom > div");
      privacy.textContent = "Session-only history";
      privacy.append(el("small", "", "Storage permission is not granted"));
      notify(
        "History is available for this window only because storage permission was not granted."
      );
    }
    history = new History(client.storage);
    settingsRecord = await client.settings.get("preferences");
    const preferences = settingsRecord?.value;
    model = preferences?.model ?? "";
    toolsEnabled = preferences?.toolsEnabled !== false;
    limits = runLimits(preferences);
    await client.network.profile("model").then((value) => connection = value).catch(report);
    await refreshEnvironment();
    updateConnection();
    await renderHistory();
    ready = true;
    prompt.focus();
    const unsubscribe = client.events.subscribe(() => {
      void refreshEnvironment().catch(report);
    }, report);
    window.addEventListener(
      "pagehide",
      () => {
        active?.abort();
        pendingReview?.(false);
        unsubscribe();
        client.dispose();
      },
      { once: true }
    );
    $("continue-run").onclick = () => {
      void send(true).catch(report);
    };
    $("send").onclick = () => {
      void send().catch(report);
    };
    $("new-chat").onclick = () => {
      void switchConversation().catch(report);
    };
    $("refresh-history").onclick = () => {
      void renderHistory().catch(report);
    };
    prompt.oninput = () => {
      conversation.draft = prompt.value;
      changed();
    };
    prompt.onkeydown = (event) => {
      if (event.key === "Enter" && !event.shiftKey && !event.isComposing) {
        event.preventDefault();
        void send().catch(report);
      }
    };
    $("toggle-sidebar").onclick = () => root.classList.toggle("sidebar-open");
    for (const id of ["settings", "model-button"])
      $(id).onclick = () => showSettings($("settings-panel").hidden);
    $("close-settings").onclick = () => showSettings(false);
    $("configure-model").onclick = () => {
      void client.network.configure({
        slot: "model",
        suggestedEndpoint: connection?.endpoint ?? "https://api.openai.com/v1/responses"
      }).then((value) => {
        if (value) connection = value;
        updateConnection();
      }).catch(report);
    };
    $("forget-model").onclick = () => {
      void client.network.forget("model").then(() => {
        connection = null;
        updateConnection();
        notify("Connection forgotten.");
      }).catch(report);
    };
    $("save-settings").onclick = () => {
      void (async () => {
        const value = $("model-input").value.trim();
        if (!value || value.length > 200)
          throw new Error("Enter a model ID of 1\u2013200 characters.");
        const rounds = $("run-rounds").valueAsNumber;
        const minutes = $("run-minutes").valueAsNumber;
        if (!Number.isSafeInteger(rounds) || rounds < 1 || !Number.isInteger(minutes) || minutes < 1 || minutes > 240)
          throw new Error(
            "Choose a positive whole number of model rounds and 1\u2013240 active minutes."
          );
        const next = await client.settings.put(
          "preferences",
          {
            model: value,
            rounds,
            minutes,
            toolsEnabled: $("tools-enabled").checked
          },
          settingsRecord?.revision ?? null
        );
        settingsRecord = next;
        model = value;
        limits = { rounds, minutes };
        toolsEnabled = $("tools-enabled").checked;
        updateConnection();
        await refreshEnvironment();
        showSettings(false);
        notify("Assistant settings saved.");
      })().catch(report);
    };
    $("export-chat").textContent = "Copy conversation JSON";
    $("export-chat").onclick = () => {
      void client.clipboard.writeText(JSON.stringify(conversation, null, 2)).then(
        () => notify(
          "Conversation JSON copied. Paste it into a local file to keep an export."
        )
      ).catch(report);
    };
    $("duplicate-chat").onclick = () => {
      void (async () => {
        await saves;
        conversation = {
          ...structuredClone(conversation),
          id: crypto.randomUUID(),
          title: conversation.title + " (copy)"
        };
        record = null;
        changed();
        await save();
        notify("Saved as a separate conversation.");
      })().catch(report);
    };
    $("delete-chat").onclick = () => {
      void (async () => {
        const result = await client.system.dialogs.messageBox({
          title: "Delete conversation?",
          message: `Delete \u201C${conversation.title}\u201D and its local attachments?`,
          kind: "warning",
          buttons: [
            { id: "cancel", label: "Keep conversation" },
            { id: "delete", label: "Delete", destructive: true }
          ],
          cancelId: "cancel",
          defaultId: "cancel"
        });
        if (result !== "delete") return;
        clearTimeout(saveTimer);
        await saves;
        await history.remove(conversation.id);
        dirty = false;
        conversation = fresh();
        record = null;
        await switchConversation();
        showSettings(false);
      })().catch(report);
    };
    $("attach-local").onclick = () => $("local-files").click();
    $("local-files").onchange = (event) => {
      const files = Array.from(event.target.files ?? []);
      event.target.value = "";
      void (async () => {
        for (const file of files) {
          if (file.type.startsWith("image/"))
            await imageAttachment(file, file.name);
          else {
            if (file.size > 3e5)
              throw new Error(
                "Choose a text file smaller than 300 KB, or paste an excerpt."
              );
            const text = new TextDecoder("utf-8", { fatal: true }).decode(
              await file.arrayBuffer()
            );
            if (text.includes("\0"))
              throw new Error(
                "This appears to be a binary file. Attach a text file or image."
              );
            addAttachment({ name: file.name, kind: "text", content: text });
          }
        }
      })().catch(report);
    };
    $("attach-remote").onclick = () => {
      void (async () => {
        const accepted = await client.environment.get();
        if (!accepted.binding) throw new Error("Connect a host first.");
        const files = await client.system.dialogs.openFile({
          title: "Attach remote text",
          multiple: true
        });
        for (const file of files ?? []) {
          const doc = await client.files.readText({
            binding: accepted.binding,
            path: file.path
          });
          addAttachment({ name: doc.name, kind: "text", content: doc.text });
        }
      })().catch(report);
    };
    $("paste-attachment").onclick = () => {
      void (async () => {
        let image;
        try {
          image = await client.clipboard.readImage();
        } catch {
        }
        if (image) {
          const canvas = document.createElement("canvas");
          canvas.width = image.width;
          canvas.height = image.height;
          canvas.getContext("2d").putImageData(
            new ImageData(
              new Uint8ClampedArray(image.rgba),
              image.width,
              image.height
            ),
            0,
            0
          );
          const blob = await new Promise(
            (resolve, reject) => canvas.toBlob(
              (blob2) => blob2 ? resolve(blob2) : reject(new Error("Cannot encode clipboard image.")),
              "image/png"
            )
          );
          await imageAttachment(blob, "Clipboard image");
        } else {
          const text = await client.clipboard.readText();
          if (!text) throw new Error("No text or image on the clipboard.");
          addAttachment({ name: "Clipboard text", kind: "text", content: text });
        }
      })().catch(report);
    };
    for (const button of root.querySelectorAll(
      "[data-prompt]"
    ))
      button.onclick = () => {
        prompt.value = button.dataset.prompt;
        conversation.draft = prompt.value;
        changed();
        prompt.focus();
      };
  }
  void start().catch((error) => {
    report(error);
    $("tools-label").textContent = "Desktop services unavailable";
  });
})();

