/* SPDX-License-Identifier: MPL-2.0 */
:root {
  --canvas-base: #19191c;
  --canvas-surface: #242427;
  --canvas-raised: #303034;
  --canvas-inset: #1d1d20;
  --canvas-text: #f2f2f5;
  --canvas-muted: #b0b0ba;
  --canvas-accent: #7ab8ff;
  --canvas-onAccent: #102745;
  --canvas-border: #48484f;
  --canvas-hover: #39393f;
  --canvas-selection: #293f5b;
  --canvas-danger: #f1a7a7;
  --canvas-dangerSoft: #462d33;
  --canvas-warning: #f2c572;
  --canvas-warningSoft: #413527;
  color-scheme: dark;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: var(--canvas-text);
  background: var(--canvas-base);
  font-synthesis: none;
}
* {
  box-sizing: border-box;
}
[hidden] {
  display: none !important;
}
html,
body,
#root {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
}
button,
input,
textarea {
  font: inherit;
}
button {
  cursor: pointer;
}
button:disabled {
  cursor: default;
  opacity: 0.4;
}
button:focus-visible,
summary:focus-visible {
  outline: 2px solid var(--canvas-accent);
  outline-offset: 3px;
}
button {
  color: inherit;
}
input,
textarea {
  color: var(--canvas-text);
}
svg {
  flex-shrink: 0;
}
.assistant-shell {
  display: flex;
  height: 100%;
  position: relative;
}
.sidebar {
  width: 226px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  background: var(--canvas-base);
  border-right: 1px solid var(--canvas-border);
  padding: 28px 17px 20px;
}
.brand {
  display: flex;
  gap: 12px;
  align-items: center;
  padding: 0 12px 29px;
  font-size: 21px;
  font-weight: 550;
  letter-spacing: -0.65px;
}
.brand-mark {
  display: grid;
  place-items: center;
  width: 34px;
  height: 38px;
  color: var(--canvas-accent);
}
.brand-mark svg {
  width: 32px;
  height: 32px;
  stroke-width: 1.3;
}
.brand-sub {
  display: block;
  font-size: 8px;
  color: var(--canvas-muted);
  letter-spacing: 2.9px;
  font-weight: 500;
  margin-top: 4px;
}
.new-chat {
  border: 1px solid var(--canvas-border);
  border-radius: 10px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 11px 10px;
  background: var(--canvas-raised);
  font-size: 11px;
  white-space: nowrap;
}
.new-chat:hover {
  background: var(--canvas-hover);
}
.new-chat svg {
  width: 16px;
}
.new-chat > span {
  margin-left: auto;
  color: var(--canvas-muted);
  font-size: 9px;
}
.history-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 27px 9px 9px;
  color: var(--canvas-muted);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 1.5px;
}
.history-heading .icon-button {
  width: 24px;
  height: 24px;
  font-size: 19px;
}
#history {
  flex: 1;
  overflow-y: auto;
  min-height: 0;
}
.history-item {
  display: flex;
  flex-direction: column;
  text-align: left;
  gap: 6px;
  border: 1px solid transparent;
  border-radius: 9px;
  padding: 12px 11px;
  width: 100%;
  margin: 3px 0;
  background: transparent;
  color: var(--canvas-muted);
}
.history-item > span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
  font-size: 11px;
}
.history-item small {
  color: var(--canvas-muted);
  font-size: 9px;
}
.history-item:hover {
  background: var(--canvas-hover);
}
.history-item.selected {
  background: var(--canvas-selection);
  border-color: var(--canvas-border);
  color: var(--canvas-text);
}
.history-empty {
  font-size: 11px;
  color: var(--canvas-muted);
  line-height: 1.7;
  margin: 15px 10px;
}
.sidebar-bottom {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  border-top: 1px solid var(--canvas-border);
  padding: 19px 10px 0;
  margin-top: 15px;
  font-size: 10px;
  color: var(--canvas-muted);
}
.sidebar-bottom small {
  display: block;
  color: var(--canvas-muted);
  font-size: 9px;
  margin-top: 6px;
}
.privacy-dot {
  width: 6px;
  height: 6px;
  background: var(--canvas-accent);
  border-radius: 50%;
  margin-top: 3px;
}
.conversation {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  flex: 1;
  background: var(--canvas-surface);
}
.chat-header {
  flex-shrink: 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  padding: 23px 29px 19px;
  border-bottom: 1px solid var(--canvas-border);
  background: var(--canvas-surface);
}
.workspace-label {
  display: flex;
  gap: 8px;
  align-items: center;
  font-size: 12px;
  color: var(--canvas-text);
  font-weight: 500;
}
.status-dot {
  height: 5px;
  width: 5px;
  border-radius: 50%;
  background: var(--canvas-accent);
}
.workspace-caption {
  display: block;
  font-size: 9px;
  color: var(--canvas-muted);
  margin-top: 6px;
  max-width: 280px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}
.icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 32px;
  width: 32px;
  padding: 0;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--canvas-muted);
}
.icon-button:hover {
  color: var(--canvas-text);
  background: var(--canvas-hover);
}
.model-button {
  display: flex;
  align-items: center;
  gap: 8px;
  max-width: 240px;
  border: 1px solid var(--canvas-border);
  border-radius: 8px;
  background: var(--canvas-raised);
  padding: 8px 10px;
  font-size: 10px;
}
.model-button span:first-of-type {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.model-button svg {
  color: var(--canvas-accent);
  height: 15px;
  width: 15px;
}
.model-button span:last-child {
  color: var(--canvas-muted);
}
.mobile-menu {
  display: none;
}
.notice {
  margin: 12px 28px 0;
  flex-shrink: 0;
  border: 1px solid var(--canvas-border);
  background: var(--canvas-selection);
  border-radius: 9px;
  padding: 11px 13px;
  font-size: 11px;
  line-height: 1.6;
  color: var(--canvas-text);
}
.notice.error {
  background: var(--canvas-dangerSoft);
  border-color: var(--canvas-danger);
  color: var(--canvas-danger);
}
.messages {
  min-height: 0;
  flex: 1;
  overflow-y: auto;
  padding: 32px 34px 20px;
  scroll-behavior: smooth;
}
.welcome {
  max-width: 645px;
  margin: 12px auto 24px;
  text-align: center;
}
.welcome-mark {
  display: grid;
  place-items: center;
  width: 67px;
  height: 67px;
  margin: 0 auto 25px;
  border: 1px solid var(--canvas-border);
  border-radius: 22px;
  background: var(--canvas-selection);
  color: var(--canvas-accent);
  box-shadow: none;
  transform: rotate(-5deg);
}
.welcome-mark svg {
  width: 36px;
  height: 36px;
  stroke-width: 1.2;
  transform: rotate(5deg);
}
.eyebrow {
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 2.1px;
  color: var(--canvas-accent);
  margin: 0 0 13px;
}
.welcome h1 {
  margin: 12px 0 18px;
  font-size: clamp(29px, 3.5vw, 44px);
  font-weight: 600;
  letter-spacing: -1.6px;
  line-height: 1.17;
  color: var(--canvas-text);
}
.welcome h1 em {
  color: var(--canvas-accent);
  font-family: inherit;
  font-style: normal;
  font-weight: 400;
  letter-spacing: -1.2px;
}
.welcome-description {
  font-size: 12px;
  line-height: 1.8;
  color: var(--canvas-muted);
  max-width: 340px;
  margin: 0 auto;
}
.suggestions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 11px;
  margin-top: 32px;
  text-align: left;
}
.suggestions button {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px;
  border: 1px solid var(--canvas-border);
  border-radius: 12px;
  background: var(--canvas-raised);
  text-align: left;
  font-size: 12px;
  color: var(--canvas-muted);
  transition:
    border-color 0.15s,
    background 0.15s;
}
.suggestions button:hover {
  border-color: var(--canvas-accent);
  background: var(--canvas-hover);
}
.suggestions button > svg {
  color: var(--canvas-accent);
}
.suggestions button > span {
  flex: 1;
  color: var(--canvas-text);
  font-size: 11px;
}
.suggestions small {
  display: block;
  font-size: 9px;
  color: var(--canvas-muted);
  margin-top: 6px;
}
#thread {
  max-width: 770px;
  margin: 0 auto;
}
.message {
  display: flex;
  gap: 14px;
  margin: 0 0 30px;
}
.avatar {
  display: grid;
  place-items: center;
  height: 29px;
  width: 29px;
  flex-shrink: 0;
  border-radius: 9px;
  background: var(--canvas-selection);
  color: var(--canvas-accent);
  font-size: 11px;
}
.message.user .avatar {
  color: var(--canvas-accent);
  background: var(--canvas-selection);
}
.message-main {
  min-width: 0;
  flex: 1;
}
.message-author {
  font-size: 11px;
  font-weight: 600;
  margin: 7px 0 12px;
  color: var(--canvas-text);
}
.message-content {
  font-size: 12px;
  color: var(--canvas-text);
  line-height: 1.8;
  overflow-wrap: anywhere;
}
.message-content p {
  white-space: pre-wrap;
  margin: 0 0 7px;
  min-height: 3px;
}
.message-content h3 {
  font-size: 14px;
  font-weight: 600;
  margin: 17px 0 9px;
  color: var(--canvas-text);
}
.message.user .message-content {
  padding: 13px 17px;
  background: var(--canvas-selection);
  border: 1px solid var(--canvas-border);
  border-radius: 0 12px 12px 12px;
}
.text-bullet {
  padding-left: 6px;
}
.inline-code {
  padding: 1px 5px;
  border-radius: 4px;
  background: var(--canvas-hover);
  color: var(--canvas-text);
  font-size: 11px;
}
.code-block {
  border: 1px solid var(--canvas-border);
  border-radius: 10px;
  overflow: hidden;
  background: var(--canvas-inset);
  margin: 14px 0;
}
.code-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--canvas-inset);
  color: var(--canvas-muted);
  padding: 2px 12px;
  font-size: 10px;
}
.code-block pre {
  padding: 14px 16px;
  margin: 0;
  overflow-x: auto;
  font:
    11px/1.7 "Cascadia Code",
    Consolas,
    monospace;
  color: var(--canvas-text);
}
.message-image {
  max-width: 100%;
  max-height: 280px;
  border-radius: 9px;
  display: block;
  margin-top: 10px;
}
.partial-label {
  color: var(--canvas-warning);
  font-size: 10px;
}
.tool-card {
  margin: 12px 0 20px 43px;
  border: 1px solid var(--canvas-border);
  border-radius: 9px;
  overflow: hidden;
  background: var(--canvas-surface);
}
.tool-card summary {
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px;
  font-size: 10px;
  color: var(--canvas-muted);
}
.tool-card summary strong {
  font-weight: 500;
  color: var(--canvas-text);
  text-transform: capitalize;
}
.tool-card summary span {
  margin-left: auto;
  font-size: 9px;
  color: var(--canvas-muted);
}
.tool-card[data-state="running"] summary span {
  color: var(--canvas-accent);
}
.tool-card pre {
  padding: 12px;
  font:
    10px/1.6 Consolas,
    monospace;
  max-height: 220px;
  white-space: pre-wrap;
  overflow: auto;
  color: var(--canvas-muted);
  border-top: 1px solid var(--canvas-border);
  margin: 0;
}
.composer-area {
  flex-shrink: 0;
  padding: 0 32px 17px;
  background: linear-gradient(transparent, var(--canvas-surface) 30%);
}
.composer {
  max-width: 790px;
  margin: 0 auto;
  padding: 15px 15px 10px;
  border: 1px solid var(--canvas-border);
  border-radius: 15px;
  background: var(--canvas-raised);
  box-shadow: 0 7px 25px rgba(0, 0, 0, 0.12);
}
.composer:focus-within {
  border-color: var(--canvas-accent);
  box-shadow:
    0 0 0 2px rgba(122, 184, 255, 0.12),
    0 7px 25px rgba(0, 0, 0, 0.12);
}
#prompt {
  width: 100%;
  min-height: 49px;
  max-height: 145px;
  resize: vertical;
  outline: none;
  border: 0;
  background: transparent;
  font-size: 12px;
  line-height: 1.7;
  padding: 1px 3px;
}
#prompt::placeholder {
  color: var(--canvas-muted);
}
.composer-tools {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 7px;
  gap: 10px;
}
.composer-tools > div {
  display: flex;
  align-items: center;
  gap: 3px;
}
.composer-hint {
  font-size: 8px;
  color: var(--canvas-muted);
  margin-left: 10px;
}
.send-button {
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: 9px;
  display: grid;
  place-items: center;
  background: var(--canvas-accent);
  color: var(--canvas-onAccent);
}
.send-button:hover {
  background: var(--canvas-accent);
}
.composer-footer {
  max-width: 790px;
  margin: 11px auto 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  color: var(--canvas-muted);
  font-size: 8px;
}
.activity {
  max-width: 780px;
  margin: 0 auto 10px;
  font-size: 10px;
  color: var(--canvas-accent);
}
.activity::before {
  content: "";
  display: inline-block;
  width: 5px;
  height: 5px;
  background: var(--canvas-accent);
  border-radius: 50%;
  margin-right: 9px;
  animation: breathe 1.8s ease-in-out infinite;
}
@keyframes breathe {
  50% {
    opacity: 0.25;
  }
}
.attachments {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}
.attachment-chip {
  display: flex;
  align-items: center;
  gap: 8px;
  border: 1px solid var(--canvas-border);
  border-radius: 8px;
  padding: 5px 6px 5px 8px;
  margin-bottom: 10px;
  background: var(--canvas-inset);
  font-size: 10px;
}
.attachment-chip img {
  width: 30px;
  height: 30px;
  object-fit: cover;
  border-radius: 4px;
}
.attachment-name {
  max-width: 160px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.attachment-chip .icon-button {
  width: 23px;
  height: 23px;
}
.attachment-chip svg {
  width: 15px;
  height: 15px;
}
.approval {
  max-width: 790px;
  margin: 0 auto 13px;
  border: 1px solid var(--canvas-warning);
  background: var(--canvas-warningSoft);
  padding: 16px;
  border-radius: 12px;
}
.approval .eyebrow {
  color: var(--canvas-warning);
  font-size: 8px;
  margin-bottom: 8px;
}
.approval h3 {
  font-size: 14px;
  margin: 0;
}
.approval-target {
  font-size: 10px;
  color: var(--canvas-text);
}
.approval pre {
  font:
    11px/1.6 Consolas,
    monospace;
  white-space: pre-wrap;
  max-height: 190px;
  overflow: auto;
  border-radius: 7px;
  background: var(--canvas-inset);
  padding: 12px;
}
.approval > div {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}
.approval button,
.settings-panel button:not(.icon-button) {
  border: 1px solid var(--canvas-border);
  border-radius: 8px;
  background: var(--canvas-raised);
  font-size: 11px;
  padding: 10px 13px;
}
.approval button.primary,
.settings-panel button.primary {
  background: var(--canvas-accent);
  color: var(--canvas-onAccent);
  border-color: var(--canvas-accent);
  font-weight: 600;
}
.settings-panel {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  width: min(350px, 100%);
  background: var(--canvas-surface);
  box-shadow: -20px 0 70px rgba(0, 0, 0, 0.25);
  border-left: 1px solid var(--canvas-border);
  padding: 27px 25px;
  overflow-y: auto;
  z-index: 3;
}
.settings-panel header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 28px;
}
.settings-panel .eyebrow {
  font-size: 8px;
}
.settings-panel h2 {
  font-size: 25px;
  font-weight: 500;
  letter-spacing: -0.7px;
  margin: 0;
}
.settings-panel > label {
  display: grid;
  gap: 8px;
  font-size: 11px;
}
.settings-panel input:not([type="checkbox"]) {
  min-width: 0;
  border: 1px solid var(--canvas-border);
  border-radius: 8px;
  padding: 11px;
  font-size: 12px;
  background: var(--canvas-inset);
}
.settings-help {
  font-size: 10px;
  line-height: 1.75;
  color: var(--canvas-muted);
}
.connection-card {
  border: 1px solid var(--canvas-border);
  border-radius: 12px;
  background: var(--canvas-raised);
  padding: 17px;
  margin: 23px 0;
}
.connection-card p {
  color: var(--canvas-text);
  font-size: 10px;
  line-height: 1.65;
  overflow-wrap: anywhere;
}
.connection-card button {
  width: 100%;
  margin-top: 8px;
}
.connection-card button.quiet {
  border-color: transparent;
  background: transparent;
  color: var(--canvas-muted);
  font-size: 10px;
}
.settings-panel .setting-check {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin: 20px 0;
}
.setting-check input {
  accent-color: var(--canvas-accent);
}
.setting-check small {
  display: block;
  font-size: 10px;
  color: var(--canvas-muted);
  line-height: 1.6;
  margin-top: 7px;
}
.settings-actions {
  display: grid;
  gap: 9px;
  margin-top: 23px;
}
.settings-actions .danger {
  color: var(--canvas-danger);
}
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-thumb {
  background: var(--canvas-border);
  border-radius: 4px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
@media (max-width: 850px) {
  .sidebar {
    width: 195px;
    padding: 23px 12px 18px;
  }
  .new-chat > span {
    display: none;
  }
  .messages {
    padding: 24px 24px 15px;
  }
  .chat-header {
    padding: 20px 24px 17px;
  }
  .composer-area {
    padding-left: 22px;
    padding-right: 22px;
  }
  .composer-hint {
    display: none;
  }
  .suggestions button {
    padding: 13px;
    gap: 8px;
  }
  .suggestions small {
    font-size: 8px;
  }
}
@media (max-width: 650px) {
  .sidebar {
    display: none;
    position: absolute;
    z-index: 4;
    top: 0;
    bottom: 0;
    width: 220px;
    box-shadow: 15px 0 35px rgba(0, 0, 0, 0.3);
  }
  .sidebar-open .sidebar {
    display: flex;
  }
  .mobile-menu {
    display: inline-flex;
  }
  .chat-header {
    padding: 16px;
    gap: 9px;
  }
  .chat-header > div:nth-child(2) {
    flex: 1;
  }
  .workspace-caption {
    max-width: 180px;
  }
  .header-actions {
    gap: 3px;
  }
  .model-button {
    max-width: 145px;
    font-size: 9px;
  }
  .messages {
    padding: 25px 19px 12px;
  }
  .welcome {
    margin-top: 7px;
  }
  .welcome h1 {
    font-size: 34px;
  }
  .welcome-description {
    max-width: 285px;
  }
  .welcome-mark {
    width: 57px;
    height: 57px;
    margin-bottom: 20px;
  }
  .suggestions {
    margin-top: 26px;
  }
  .suggestions button {
    padding: 12px 10px;
    font-size: 9px;
  }
  .suggestions button > span {
    font-size: 10px;
  }
  .suggestions small {
    line-height: 1.5;
  }
  .composer-area {
    padding: 0 15px 12px;
  }
  .composer-footer > span:last-child {
    display: none;
  }
  .notice {
    margin-left: 15px;
    margin-right: 15px;
  }
}
@media (max-height: 700px) and (min-width: 651px) {
  .welcome {
    margin-top: 0;
  }
  .welcome-mark {
    width: 48px;
    height: 48px;
    margin-bottom: 16px;
    border-radius: 16px;
  }
  .welcome h1 {
    font-size: 32px;
    margin-bottom: 13px;
  }
  .welcome-description {
    font-size: 11px;
  }
  .suggestions {
    margin-top: 23px;
  }
  .suggestions button {
    padding: 12px;
  }
  .messages {
    padding-top: 22px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .messages {
    scroll-behavior: auto;
  }
  .activity::before {
    animation: none;
  }
}

.run-paused {
  max-width: 790px;
  margin: 0 auto 12px;
  padding: 12px;
  border: 1px solid var(--canvas-border);
  border-radius: 10px;
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 11px;
}
.run-paused span {
  flex: 1;
}
.run-paused button {
  border: 1px solid var(--canvas-border);
  border-radius: 7px;
  padding: 8px 12px;
  color: var(--canvas-onAccent);
  background: var(--canvas-selection);
  white-space: nowrap;
}

.host-context {
  padding: 9px 28px;
  border-bottom: 1px solid var(--canvas-border);
  color: var(--canvas-text);
  background: var(--canvas-selection);
  font-size: 11px;
  line-height: 1.5;
  flex-shrink: 0;
  overflow-wrap: anywhere;
}
.host-change {
  margin: 24px 0;
  padding: 12px 16px;
  border: 1px solid var(--canvas-border);
  border-radius: 10px;
  background: var(--canvas-selection);
  color: var(--canvas-text);
  text-align: center;
  font-size: 12px;
  overflow-wrap: anywhere;
}

.chat-header > div:nth-child(2) {
  min-width: 0;
}
.workspace-label {
  min-width: 0;
}
#host-name {
  overflow-wrap: anywhere;
}
.status-dot,
.header-actions {
  flex-shrink: 0;
}

/* Clear controls at desktop and compact sizes. */
::selection {
  background: var(--canvas-selection);
  color: var(--canvas-text);
}
#send:hover {
  filter: brightness(1.08);
}
.welcome-mark {
  transform: none;
  box-shadow: none;
}
.welcome-mark svg {
  transform: none;
}

.table-scroll {
  max-width: 100%;
  overflow-x: auto;
  margin: 16px 0;
  border: 1px solid var(--canvas-border);
  border-radius: 9px;
}
.table-scroll table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
  line-height: 1.5;
}
.table-scroll th {
  background: var(--canvas-raised);
  text-align: left;
  font-weight: 600;
  white-space: nowrap;
}
.table-scroll th,
.table-scroll td {
  padding: 9px 12px;
  border-bottom: 1px solid var(--canvas-border);
  vertical-align: top;
}
.table-scroll tr:last-child td {
  border-bottom: 0;
}
.tool-card {
  margin: 3px 0 3px 43px;
  border: 1px solid transparent;
  background: transparent;
  border-radius: 7px;
}
.tool-card + .tool-card {
  margin-top: 0;
}
.tool-card summary {
  min-height: 28px;
  padding: 4px 6px;
  gap: 7px;
  color: var(--canvas-muted);
}
.tool-card summary::-webkit-details-marker {
  display: none;
}
.tool-card summary::before {
  content: "›";
  font-size: 15px;
  line-height: 1;
}
.tool-card[open] summary::before {
  transform: rotate(90deg);
}
.tool-card summary svg {
  width: 14px;
  height: 14px;
}
.tool-card summary strong {
  color: inherit;
  font-size: 11px;
  font-weight: 400;
}
.tool-card summary span {
  font-size: 9px;
}
.tool-card summary:hover {
  background: var(--canvas-hover);
}
.tool-card[open] {
  background: var(--canvas-inset);
  border-color: var(--canvas-border);
  margin-top: 7px;
  margin-bottom: 9px;
}
.tool-card[data-state="running"] summary {
  color: var(--canvas-accent);
}
.tool-card[data-state="failed"] summary {
  color: var(--canvas-danger);
}
.tool-card pre {
  max-height: 260px;
  overflow: auto;
  margin: 0;
  padding: 10px 12px;
}
.tool-card .tool-result:empty {
  display: none;
}
.tool-card .tool-input {
  color: var(--canvas-muted);
}
@media (max-width: 650px) {
  .tool-card {
    margin-left: 0;
  }
}

/* Override the desktop iframe's fallback body typography and color. */
body {
  color: var(--canvas-text);
  background: var(--canvas-base);
  color-scheme: inherit;
  font: inherit;
}
